from control import *
def capture(name):
 ev('''(async()=>{await document.fonts.ready;await Promise.all([...document.querySelectorAll('[data-testid=shop-scene]')].flatMap(e=>e.getAnimations({subtree:true})).filter(a=>a.effect?.getTiming().iterations!==Infinity).map(a=>a.finished.catch(e=>{if(e.name!=='AbortError')throw e})));return true;})()''')
 data=ev('''(()=>{const ids=['shop-scene','shop-summary-stat-attack','shop-summary-reason','shop-detail-open','shop-comparison','shop-stat-attack','shop-preview-reason','shop-stat-slot','shop-detail-card'];const geo=e=>{if(!e)return {present:false,rect:null,display:null};return {present:true,text:e.innerText,data:{...e.dataset},rect:e.getBoundingClientRect().toJSON(),display:getComputedStyle(e).display,visibility:getComputedStyle(e).visibility,ancestors:[e.parentElement,e.parentElement?.parentElement].filter(Boolean).map(a=>({class:a.className,display:getComputedStyle(a).display,rect:a.getBoundingClientRect().toJSON()}))}};const state=window.__oprnDebug.readState();return {url:location.href,viewport:{width:innerWidth,height:innerHeight},selectors:Object.fromEntries(ids.map(id=>[id,geo(document.querySelector('[data-testid="'+id+'"]'))])),rows:[...document.querySelectorAll('.runtime-shop-item-row')].map(e=>({testid:e.dataset.testid,data:{...e.dataset},selected:e.getAttribute('aria-current'),text:e.innerText,rect:e.getBoundingClientRect().toJSON()})),focus:document.activeElement?.dataset.testid,state:{mapId:state.currentMapId,x:state.x,y:state.y,gold:state.gold,inventory:state.inventory,partyActorIds:state.partyActorIds},mirror:JSON.parse(document.querySelector('[data-testid=runtime-state-json]').textContent),resources:performance.getEntriesByType('resource').map(e=>e.name)}})()''')
 (OUT/(name+'.json')).write_text(json.dumps(data,indent=2,ensure_ascii=False));shot(name+'.png');return data
if __name__=='__main__':print(json.dumps(capture('04-stock-geometry')['selectors'],indent=2,ensure_ascii=False))
